-- MiniMarket 0.6.23: immutable non-fiscal order documents and provider-neutral fiscal evidence.
-- No fiscal receipt is generated by this migration or by saving an invoice.
-- No historical changes to payment, refund, stock or orders.
CREATE TABLE IF NOT EXISTS #__minimarket_order_documents (
 id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
 order_id INT UNSIGNED NOT NULL,
 document_type VARCHAR(24) NOT NULL DEFAULT 'invoice',
 document_number VARCHAR(60) NOT NULL,
 snapshot_json MEDIUMTEXT NOT NULL,
 snapshot_sha256 CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 total_cents BIGINT UNSIGNED NOT NULL,
 currency CHAR(3) NOT NULL,
 created_by INT UNSIGNED NOT NULL,
 created_at DATETIME NOT NULL,
 PRIMARY KEY (id),
 UNIQUE KEY uq_mm_order_document (order_id,document_type),
 UNIQUE KEY uq_mm_document_number (document_number),
 KEY idx_mm_document_created (created_at),
 CONSTRAINT fk_mm_document_order FOREIGN KEY (order_id)
  REFERENCES #__minimarket_orders(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Only a future, explicitly connected fiscal adapter may create/advance these rows.
-- Operation types and evidence are not proof of issuance without provider confirmation.
CREATE TABLE IF NOT EXISTS #__minimarket_fiscal_operations (
 id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
 order_id INT UNSIGNED NOT NULL,
 payment_record_id BIGINT UNSIGNED NULL,
 return_id INT UNSIGNED NULL,
 operation_type VARCHAR(16) NOT NULL,
 provider_code VARCHAR(32) NOT NULL,
 request_key CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 provider_operation_id VARCHAR(128) NULL,
 status VARCHAR(20) NOT NULL DEFAULT 'pending',
 fiscal_reference VARCHAR(128) NULL,
 receipt_url VARCHAR(2048) NULL,
 last_error_code VARCHAR(64) NULL,
 last_error_message VARCHAR(1024) NULL,
 created_at DATETIME NOT NULL,
 updated_at DATETIME NULL,
 confirmed_at DATETIME NULL,
 PRIMARY KEY (id),
 UNIQUE KEY uq_mm_fiscal_request (request_key),
 UNIQUE KEY uq_mm_fiscal_provider_ref (provider_code,provider_operation_id),
 KEY idx_mm_fiscal_order (order_id,id),
 KEY idx_mm_fiscal_status (status,created_at),
 CONSTRAINT fk_mm_fiscal_order FOREIGN KEY (order_id)
  REFERENCES #__minimarket_orders(id) ON DELETE RESTRICT,
 CONSTRAINT fk_mm_fiscal_payment FOREIGN KEY (payment_record_id)
  REFERENCES #__minimarket_payment_records(id) ON DELETE RESTRICT,
 CONSTRAINT fk_mm_fiscal_return FOREIGN KEY (return_id)
  REFERENCES #__minimarket_returns(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS #__minimarket_fiscal_operation_events (
 id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
 fiscal_operation_id BIGINT UNSIGNED NOT NULL,
 event_key CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 previous_status VARCHAR(20) NULL,
 status VARCHAR(20) NOT NULL,
 provider_reference VARCHAR(128) NULL,
 error_code VARCHAR(64) NULL,
 occurred_at DATETIME NOT NULL,
 PRIMARY KEY (id),
 UNIQUE KEY uq_mm_fiscal_event_key (fiscal_operation_id,event_key),
 KEY idx_mm_fiscal_event_time (fiscal_operation_id,occurred_at),
 CONSTRAINT fk_mm_fiscal_event_operation FOREIGN KEY (fiscal_operation_id)
  REFERENCES #__minimarket_fiscal_operations(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
